-- Abrir en VPS_Practica03. Exportar la celda metadatos_vps como texto JSON.
SELECT JSON_OBJECT(
 'schema','bd_test','entorno','MySQL del VPS','fecha',CURRENT_DATE(),'version',VERSION(),
 'tables', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('TABLE_NAME',TABLE_NAME,'TABLE_TYPE',TABLE_TYPE,'ENGINE',ENGINE,'TABLE_COMMENT',TABLE_COMMENT)),JSON_ARRAY()) FROM information_schema.TABLES WHERE TABLE_SCHEMA='bd_test'),
 'columns', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('TABLE_NAME',TABLE_NAME,'COLUMN_NAME',COLUMN_NAME,'ORDINAL_POSITION',ORDINAL_POSITION,'COLUMN_TYPE',COLUMN_TYPE,'IS_NULLABLE',IS_NULLABLE,'COLUMN_DEFAULT',COLUMN_DEFAULT,'COLUMN_KEY',COLUMN_KEY,'EXTRA',EXTRA,'COLUMN_COMMENT',COLUMN_COMMENT)),JSON_ARRAY()) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='bd_test' AND TABLE_NAME IN (SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='bd_test' AND TABLE_TYPE='BASE TABLE')),
 'indexes', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('TABLE_NAME',TABLE_NAME,'INDEX_NAME',INDEX_NAME,'NON_UNIQUE',NON_UNIQUE,'SEQ_IN_INDEX',SEQ_IN_INDEX,'COLUMN_NAME',COLUMN_NAME,'SUB_PART',SUB_PART,'INDEX_TYPE',INDEX_TYPE)),JSON_ARRAY()) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='bd_test'),
 'foreign_keys', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('TABLE_NAME',TABLE_NAME,'CONSTRAINT_NAME',CONSTRAINT_NAME,'COLUMN_NAME',COLUMN_NAME,'ORDINAL_POSITION',ORDINAL_POSITION,'REFERENCED_TABLE_NAME',REFERENCED_TABLE_NAME,'REFERENCED_COLUMN_NAME',REFERENCED_COLUMN_NAME)),JSON_ARRAY()) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA='bd_test' AND REFERENCED_TABLE_NAME IS NOT NULL),
 'checks', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('CONSTRAINT_NAME',CONSTRAINT_NAME,'CHECK_CLAUSE',CHECK_CLAUSE)),JSON_ARRAY()) FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='bd_test'),
 'triggers', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('TRIGGER_NAME',TRIGGER_NAME,'EVENT_OBJECT_TABLE',EVENT_OBJECT_TABLE,'ACTION_TIMING',ACTION_TIMING,'EVENT_MANIPULATION',EVENT_MANIPULATION)),JSON_ARRAY()) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='bd_test'),
 'events', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('EVENT_NAME',EVENT_NAME,'STATUS',STATUS,'LAST_EXECUTED',LAST_EXECUTED)),JSON_ARRAY()) FROM information_schema.EVENTS WHERE EVENT_SCHEMA='bd_test'),
 'routines', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('ROUTINE_NAME',ROUTINE_NAME,'ROUTINE_TYPE',ROUTINE_TYPE)),JSON_ARRAY()) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA='bd_test')
) AS metadatos_vps;
